/**
 * POST Validator Helper
 * Validates meeting against POST framework requirements.
 * Validation runs in two places:
 * 1. Manual "Check Meeting" button in task pane
 * 2. OnAppointmentSend smart alert (if Mailbox 1.12 available)
 */

import { isPostComplete } from "./customProperties";
import { getAttendeeCount, getDurationMinutes } from "./meetingAnalyzer";

export interface ValidationResult {
  isValid: boolean;
  warnings: string[];
  errors: string[];
}

/**
 * Validate meeting against all POST framework requirements
 */
export async function validateMeeting(): Promise<ValidationResult> {
  const result: ValidationResult = {
    isValid: true,
    warnings: [],
    errors: [],
  };

  try {
    // Check attendee count
    const attendeeCount = await getAttendeeCount();
    if (attendeeCount > 7) {
      result.warnings.push(
        `This meeting has ${attendeeCount} attendees. Optimal size is 5-7.`
      );
    }

    // Check duration
    const duration = await getDurationMinutes();
    if (duration > 45) {
      result.warnings.push(
        `Consider shortening this ${duration} min meeting to 30 or 45 min.`
      );
    }

    // Check POST completion from custom properties
    const postComplete = await isPostComplete();
    if (!postComplete) {
      result.errors.push(
        "Meeting is missing POST framework.\n\nTo fix: Click 'Don't Send', then open 'POST Meeting v3' from the ribbon (or '...' menu). Fill in Purpose, Outcomes, Structure, and Timing, then click 'Insert POST into Body'."
      );
      result.isValid = false;
    }
  } catch (error) {
    console.error("Validation error:", error);
    // Don't block on validation errors - allow sending
    result.warnings.push("Could not complete all validation checks.");
  }

  return result;
}

/**
 * Format validation result for display in task pane
 */
export function formatValidationResult(result: ValidationResult): string {
  const lines: string[] = [];

  if (result.isValid && result.warnings.length === 0) {
    lines.push("All checks passed! Meeting is ready to send.");
  } else {
    if (result.errors.length > 0) {
      lines.push("Issues that should be addressed:");
      result.errors.forEach((error) => lines.push(`  - ${error}`));
    }

    if (result.warnings.length > 0) {
      if (result.errors.length > 0) lines.push("");
      lines.push("Suggestions:");
      result.warnings.forEach((warning) => lines.push(`  - ${warning}`));
    }
  }

  return lines.join("\n");
}

/**
 * Format validation result for smart alert error message
 */
export function formatValidationForAlert(result: ValidationResult): string {
  const messages: string[] = [];

  if (result.errors.length > 0) {
    messages.push(...result.errors);
  }

  if (result.warnings.length > 0) {
    messages.push(...result.warnings);
  }

  return messages.join("\n\n");
}

/**
 * Check if Mailbox 1.12 is supported (required for OnAppointmentSend)
 */
export function isSmartAlertsSupported(): boolean {
  return Office.context.requirements.isSetSupported("Mailbox", "1.12");
}

/**
 * Validate individual POST fields
 */
export interface FieldValidation {
  purpose: boolean;
  outcomes: boolean;
  structure: boolean;
  timing: boolean;
}

export function validateFields(data: {
  purpose: string;
  outcomes: string;
  structure: string;
  timing: string;
}): FieldValidation {
  return {
    purpose: data.purpose.trim().length > 0,
    outcomes: data.outcomes.trim().length > 0,
    structure: data.structure.trim().length > 0,
    timing: data.timing.trim().length > 0,
  };
}

/**
 * Check if all fields are valid
 */
export function allFieldsValid(validation: FieldValidation): boolean {
  return (
    validation.purpose &&
    validation.outcomes &&
    validation.structure &&
    validation.timing
  );
}
