/**
 * Custom Properties Helper
 * Manages POST framework data storage using Office.js custom properties.
 * Custom properties are preferred over body parsing because they're:
 * - Reliable across all clients
 * - Not affected by HTML formatting differences
 * - Survive user edits to meeting body
 * - Fast to read/write
 */

export interface PostData {
  purpose: string;
  outcomes: string;
  structure: string;
  timing: string;
  isComplete: boolean;
  lastUpdated: string;
}

/**
 * Save POST framework data to custom properties
 */
export function savePostData(data: PostData): Promise<void> {
  return new Promise((resolve, reject) => {
    Office.context.mailbox.item?.loadCustomPropertiesAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Failed) {
        reject(result.error);
        return;
      }
      const props = result.value;
      props.set("postData", JSON.stringify(data));
      props.set("postComplete", String(data.isComplete));
      props.saveAsync((saveResult) => {
        if (saveResult.status === Office.AsyncResultStatus.Succeeded) {
          resolve();
        } else {
          reject(saveResult.error);
        }
      });
    });
  });
}

/**
 * Load POST framework data from custom properties
 */
export function loadPostData(): Promise<PostData | null> {
  return new Promise((resolve, reject) => {
    Office.context.mailbox.item?.loadCustomPropertiesAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Failed) {
        reject(result.error);
        return;
      }
      const props = result.value;
      const dataStr = props.get("postData");
      if (dataStr) {
        try {
          resolve(JSON.parse(dataStr));
        } catch {
          resolve(null);
        }
      } else {
        resolve(null);
      }
    });
  });
}

/**
 * Check if POST framework is complete (for OnAppointmentSend validation)
 */
export function isPostComplete(): Promise<boolean> {
  return new Promise((resolve, reject) => {
    Office.context.mailbox.item?.loadCustomPropertiesAsync((result) => {
      if (result.status === Office.AsyncResultStatus.Failed) {
        reject(result.error);
        return;
      }
      const props = result.value;
      resolve(props.get("postComplete") === "true");
    });
  });
}

/**
 * Create an empty POST data object
 */
export function createEmptyPostData(): PostData {
  return {
    purpose: "",
    outcomes: "",
    structure: "",
    timing: "",
    isComplete: false,
    lastUpdated: new Date().toISOString(),
  };
}

/**
 * Check if all required POST fields have content
 */
export function validatePostData(data: PostData): boolean {
  return (
    data.purpose.trim().length > 0 &&
    data.outcomes.trim().length > 0 &&
    data.structure.trim().length > 0 &&
    data.timing.trim().length > 0
  );
}
