/**
 * Commands Handler
 * Event-based activation handlers for appointment compose and send events.
 */

import { validateMeeting, formatValidationForAlert, isSmartAlertsSupported } from "../helpers/postValidator";
import { getAttendeeCount, getDurationMinutes } from "../helpers/meetingAnalyzer";

// Ensure Office.js is initialized
Office.onReady(() => {
  // Register event handlers
  registerEventHandlers();
});

/**
 * Register event handlers with Office
 */
function registerEventHandlers(): void {
  // OnAppointmentComposeActivate is always registered
  Office.actions.associate("onAppointmentComposeActivate", onAppointmentComposeActivate);

  // OnAppointmentSend requires Mailbox 1.12
  if (isSmartAlertsSupported()) {
    Office.actions.associate("onAppointmentSend", onAppointmentSend);
    console.log("Smart alerts (OnAppointmentSend) registered - Mailbox 1.12 supported");
  } else {
    console.log("Smart alerts not available - Mailbox 1.12 not supported");
  }
}

/**
 * OnAppointmentComposeActivate Event Handler
 * Fires when user creates or opens a meeting for editing.
 * Shows a notification prompting user to open the task pane.
 */
async function onAppointmentComposeActivate(
  event: Office.AddinCommands.Event
): Promise<void> {
  try {
    // Get meeting info for the notification
    const [attendeeCount, duration] = await Promise.all([
      getAttendeeCount(),
      getDurationMinutes(),
    ]);

    // Build notification message
    let message = "Complete the POST framework. Click 'POST Meeting v3' in the ribbon (or '...' menu), fill in the fields, and click 'Insert POST into Body'.";

    const tips: string[] = [];
    if (attendeeCount > 7) {
      tips.push(`${attendeeCount} attendees (optimal: 5-7)`);
    }
    if (duration > 45) {
      tips.push(`${duration} min (consider 30-45 min)`);
    }

    if (tips.length > 0) {
      message = `${tips.join(", ")}. Open POST Meeting to review.`;
    }

    // Show notification - user must click ribbon button to open task pane
    // Cannot programmatically open task pane from event-based activation
    Office.context.mailbox.item?.notificationMessages.addAsync(
      "postReminder",
      {
        type: Office.MailboxEnums.ItemNotificationMessageType.InformationalMessage,
        message: message,
        icon: "Icon.16x16",
        persistent: true,
      },
      (result) => {
        if (result.status === Office.AsyncResultStatus.Failed) {
          console.error("Failed to add notification:", result.error);
        }
      }
    );
  } catch (error) {
    console.error("Error in onAppointmentComposeActivate:", error);
  }

  // Always complete the event
  event.completed();
}

/**
 * OnAppointmentSend Event Handler (Smart Alert)
 * Fires when user clicks Send. Requires Mailbox 1.12.
 * Validates POST completion and can soft-block the send.
 */
async function onAppointmentSend(
  event: Office.AddinCommands.Event
): Promise<void> {
  try {
    const result = await validateMeeting();

    if (!result.isValid) {
      // Soft block - user can override with "Send Anyway"
      event.completed({
        allowEvent: false,
        errorMessage: formatValidationForAlert(result),
      } as Office.AddinCommands.EventCompletedOptions);
    } else if (result.warnings.length > 0) {
      // Allow but show info notification about warnings
      // Note: Can't show blocking dialog for warnings, just allow send
      // Warnings were already shown in task pane
      event.completed({ allowEvent: true });
    } else {
      // All good - allow send
      event.completed({ allowEvent: true });
    }
  } catch (error) {
    console.error("Error in onAppointmentSend:", error);
    // Don't block on errors - allow sending
    event.completed({ allowEvent: true });
  }
}

// Make functions available globally for Office.actions.associate
(globalThis as Record<string, unknown>).onAppointmentComposeActivate = onAppointmentComposeActivate;
(globalThis as Record<string, unknown>).onAppointmentSend = onAppointmentSend;
